import{_ as t,o,c as a,ao as r}from"./chunks/framework.Cb4tnR4I.js";const u=JSON.parse('{"title":"Things That Will Bite You","description":"","frontmatter":{},"headers":[],"relativePath":"reference/pitfalls.md","filePath":"reference/pitfalls.md","lastUpdated":null}'),s={name:"reference/pitfalls.md"};function i(n,e,l,d,c,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="Things-That-Will-Bite-You" tabindex="-1">Things That Will Bite You <a class="header-anchor" href="#Things-That-Will-Bite-You" aria-label="Permalink to &quot;Things That Will Bite You {#Things-That-Will-Bite-You}&quot;">​</a></h1><ul><li><p><strong>The stimulus sign is inverted relative to a cell model.</strong> A protocol returns <code>Iₐₚₚ</code> in PDE form, where positive depolarizes; a CytoZoo cell model&#39;s internal stimulus is a membrane current, where negative depolarizes. See <a href="/FlashBang.jl/dev/reference/api#FlashBang.AbstractStimulationProtocol"><code>AbstractStimulationProtocol</code></a>. Stimulation belongs to the diffusion half — the cell model&#39;s own stimulus must be off, and <a href="/FlashBang.jl/dev/reference/api#FlashBang.MonodomainModel"><code>MonodomainModel</code></a> warns when it can tell that it is not.</p></li><li><p><strong>The grid is cell-centered.</strong> <code>n</code> cells across a length <code>L</code> put the first node at <code>Δx/2</code>, not at <code>0</code>. Comparisons against a vertex-centered reference differ at <code>O(Δx)</code>.</p></li><li><p><strong>Only zero-flux boundaries.</strong> Anything else raises an <code>ArgumentError</code> naming the face.</p></li><li><p><strong>One semidiscretization per concurrent solve.</strong> The prepared operator inside the diffusion half owns scratch buffers and is stateful and single-threaded. For a threaded <code>EnsembleProblem</code>, build each trajectory&#39;s problem from its own <code>semidiscretize</code> call inside <code>prob_func</code>; the default <code>prob_func</code> hands every trajectory the same <code>f</code>.</p></li><li><p><strong>Saving is opt-in and full-state.</strong> See <a href="./../guides/saving">Saving Output</a>; observe per-step quantities with a <a href="/FlashBang.jl/dev/reference/api#FlashBang.StateObserver-Tuple{Any}"><code>StateObserver</code></a> rather than saving every step.</p></li><li><p><strong><code>solve</code> clashes with MatrixFreeOperators&#39;.</strong> Both packages export a <code>solve</code>; after <code>using FlashBang, MatrixFreeOperators</code>, write <code>FlashBang.solve</code>, or import MatrixFreeOperators by name.</p></li><li><p><strong>Use <code>Float64</code>.</strong> <code>Float32</code> runs, but the ArmyHeart reference measured non-finite results across 58.6% of the ToRORd parameter space in single precision.</p></li><li><p><strong>On a GPU, everything that enters a kernel must be isbits</strong> — the cell model, the stimulus, and any spatial overrides. See <a href="./../guides/gpu">Running on a GPU</a>.</p></li></ul>',2)])])}const g=t(s,[["render",i]]);export{u as __pageData,g as default};
